// Build digest prompt dari list briefs
const data = $input.first().json;
const briefs = data.briefs || [];

if (briefs.length === 0) {
  return {
    skip: true,
    note: 'No active briefs, skip digest',
  };
}

const lines = briefs.map((b, i) => {
  const title = b.result?.title || b.briefId;
  const status = b.status;
  const summary = (b.result?.summary || '').slice(0, 200);
  return `${i + 1}. [${status}] ${title}\n   ${summary}`;
}).join('\n\n');

return {
  skip: false,
  briefCount: briefs.length,
  digestPrompt: `Sintesakan kondisi Gerai 1000 Pintu hari ini dari ${briefs.length} brief aktif berikut. Format: 3 prioritas urutan, 1 risiko utama, 1 next action konkret yang harus Matthew lakukan hari ini. Maximum 250 kata.\n\nBrief aktif:\n${lines}`,
};

// Format digest output. Akan dikirim ke channel notif (email/Discord/PWA push) di node berikutnya.
// Untuk MVP, sekarang cuma log + opsi kirim ke webhook callback app.
const result = $input.first().json;
const digestText = result.text || 'Atmaja synth tidak tersedia';
const now = new Date();
const dateStr = now.toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

return {
  date: dateStr,
  digest: digestText,
  model: result.model || 'unknown',
  briefCount: $('Build Digest Prompt').first().json.briefCount,
  note: 'Digest siap. Sambungkan ke channel notif (email, Discord, atau PWA push) untuk auto-kirim ke Matthew.',
};
